head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.gAcptNo;
scwin.gIsurCd;
scwin.vScrenID = 'ULDSTF10011.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetParentValue = function() {
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;
    //alert("회사코드:"+gIsurCd);

};
scwin.fn_SetCode = function() {
    //  기간 from~ to  셋팅	
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 1)); // 한달전 날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd"));

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !조건체크--;
사용자;
클릭-- > function() {
    // 일자 체크
    if ($c.stf.getObjectValue(edt_FromDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_ToDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    scwin.fn_Search();
};


// 화면 로딩시 디폴트 검색
scwin.fn_Search = function() {
    var url = "/DisclosureSearch.do?method=listAllDsclAcptIsur&inputMessageId=PERIODDSCLISUR_IN" + "&outputMessageId=PERIODDSCLISUR_OUT" + "&ISUR_CD=" + scwin.gIsurCd + "&TYPE=PE" + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_DsclAcptListAll.DataID = encodeURI(url);
    dts_DsclAcptListAll.reset();
    $c.cm.ShowWin(grd_DsclAcptListAll);
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclAcptListAll.getCellData(eval(obj), "ACPT_NO");
    gMainFormCd = dts_DsclAcptListAll.getCellData(eval(obj), "FORM_CD");
    gFormVer = dts_DsclAcptListAll.getCellData(eval(obj), "FORM_VER");
    scwin.gIsurCd = dts_DsclAcptListAll.getCellData(eval(obj), "ISUR_CD");
    //alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};
scwin.grd_DsclAcptListAll_OnClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "PROCS_DATE") {
        // 부모창에 셋팅하기
        $c.frame.path("../").txb_rediscls_acptno.setValue(dts_DsclAcptListAll.getCellData(row, "ACPT_NO"));
        $c.frame.path("../").txb_acpt_ddtm.setValue(dts_DsclAcptListAll.getCellData(row, "PROCS_DATE"));
        $c.frame.path("../").txb_doc_title.setValue(dts_DsclAcptListAll.getCellData(row, "DOC_TITLE"));
        await $c.frame.CloseFrame();
    }
};
scwin.grd_DsclAcptListAll_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    var result = "";
    if (colid == "DOC_TITLE") {
        /*
        var url = "/dsclproc/ULDSTF10001.gfm";
        var winTitle ="임시제목  - (회사명/보고서명/접수날짜)";
        frame.CreateDialogFrame("gform", url , winTitle ,100, 10, 1000, 800, "window" );
        //frame.CreateFrame("viewer", url , winTitle ,10, 10, 1000, 800, "window" , 0, 0, true);
        */
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, 'R');
    } else if (colid == "ACPT_DATE") {
        // 부모창에 셋팅하기
        $c.frame.path("../").txb_acptno.setValue(dts_DsclAcptListAll.getCellData(row, "ACPT_NO"));
        $c.frame.path("../").txb_acpt_ddtm.setValue(dts_DsclAcptListAll.getCellData(row, "ACPT_DATE"));
        $c.frame.path("../").txb_doc_title.setValue(dts_DsclAcptListAll.getCellData(row, "DOC_TITLE"));
        await $c.frame.CloseFrame();
    }
};
scwin.dts_DsclAcptListAll_OnLoadError = function() {
    $c.stf.alert_error(dts_DsclAcptListAll);
};
scwin.dts_DsclAcptListAll_OnLoadCompleted = function(rowcount) {
    if (dts_DsclAcptListAll.errorMsg) {
        $c.win.alert(dts_DsclAcptListAll.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    $c.cm.CloseWin();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_DsclAcptListAll, "제출보고서 목록", "", "8");
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_GetParentValue();
    scwin.fn_SetCode();
    // 가우스헤더 셋팅
    //dts_StudyCond.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DSCLSTUDYCOND_IN";
    //dts_StudyCond.reset();	

    scwin.fn_Search();
};
